-- Generated by scripts/build_compiled.py from src/fraudrules/rules/check-kiting/ck-001-circular-checks.yaml. Do not edit.
-- CK-001 Checks flowing both ways with the same counterparty within days
SELECT
  'CK-001' AS rule_id,
  'transactions' AS anchor_table,
  a.id AS anchor_id
FROM transactions AS a
JOIN transactions AS b
  ON b.account_id = a.account_id
  AND b.counterparty_id = a.counterparty_id
  AND b.ts <= a.ts
  AND b.ts > a.ts - 432000
WHERE
  a.channel = 'check' AND b.channel = 'check'
GROUP BY
  a.id
HAVING
  (
    COUNT(CASE WHEN b.direction = 'in' THEN 1 END) >= 2
    AND COUNT(CASE WHEN b.direction = 'out' THEN 1 END) >= 2
    AND SUM(CASE WHEN b.direction = 'in' THEN b.amount_cents END) >= 500000
  );
